def build_oceania():
    count = 0
    for code, (name, translations) in OCEANIA_LANGS.items():
        build_po(code, name, translations)
        count += 1
    return count

if __name__ == "__main__":
    print(f"Built {build_oceania()} Oceanic languages.")
